Cypher query: MATCH (n:__Entity__)
WHERE (
  toLower(n.name) CONTAINS "speed limit"
  OR any(alias IN coalesce(n.aliases, []) WHERE toLower(alias) CONTAINS "speed limit")
  OR toLower(n.name) CONTAINS "repeater"
  OR any(alias IN coalesce(n.aliases, []) WHERE toLower(alias) CONTAINS "repeater")
  OR (
    toLower(n.name) CONTAINS "uniform"
    AND toLower(n.name) CONTAINS "traffic"
    AND toLower(n.name) CONTAINS "control"
  )
  OR any(alias IN coalesce(n.aliases, []) WHERE
    toLower(alias) CONTAINS "uniform"
    AND toLower(alias) CONTAINS "traffic"
    AND toLower(alias) CONTAINS "control"
  )
)
OPTIONAL MATCH (n)-[r]-(m:__Entity__)
OPTIONAL MATCH (n)-[:FROM_CHUNK]->(c:Chunk)-[:FROM_DOCUMENT]->(d:Document)
