OPTIONAL MATCH (n)-[:PART_OF]-(e:Work)
RETURN n.name AS series, n.episode_count AS episode_count, coalesce(n.episodes, e.episodes) AS episode_list, e.name AS episode, e.episode_number AS episode_number
